1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	export interface Incident {
19	  cause: string;
20	  damages: Damage[];
21	}
22	
23	export interface ClaimStep {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	}
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export interface Customer {
32	  yearsWithMHPCO: number;
33	}
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface ScenarioOutput {
41	  results: unknown[];
42	}
43	
44	const PROCESSING_FEE = 5;
45	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
46	const LOYALTY_YEARS = 2;
47	const LOYALTY_DISCOUNT_RATE = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
49	
50	/** The MHPCO insures exactly these item types; anything else is unknown. */
51	interface ItemTypeTerms {
52	  basePremium: number;
53	  insuranceValue: number;
54	}
55	
56	const ITEM_TYPES: Record<string, ItemTypeTerms | undefined> = {
57	  sword: { basePremium: 100, insuranceValue: 1000 },
58	  amulet: { basePremium: 60, insuranceValue: 600 },
59	  staff: { basePremium: 80, insuranceValue: 800 },
60	  potion: { basePremium: 40, insuranceValue: 400 },
61	  rune: { basePremium: 25, insuranceValue: 250 },
62	  moonstone: { basePremium: 25, insuranceValue: 250 },
63	};
64	
65	const termsOfType = (type: string): ItemTypeTerms => {
66	  const terms = ITEM_TYPES[type];
67	  if (terms === undefined) {
68	    throw new Error(`unknown item type: ${type}`);
69	  }
70	  return terms;
71	};
72	
73	const basePremiumOfType = (type: string): number => termsOfType(type).basePremium;
74	
75	const CURSE_SURCHARGE_RATE = 0.5;
76	const ENCHANTMENT_SURCHARGE_LEVEL = 5;
77	const ENCHANTMENT_SURCHARGE_RATE = 0.3;
78	
79	/** An item without an enchantment counts as enchantment 0. */
80	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
81	
82	const isCursed = (item: Item): boolean => item.cursed === true;
83	
84	const qualifiesForEnchantmentSurcharge = (item: Item): boolean =>
85	  enchantmentOf(item) >= ENCHANTMENT_SURCHARGE_LEVEL;
86	
87	/** Item-specific modifiers apply to the base premium of the affected item only. */
88	const itemSurchargesOf = (item: Item): number => {
89	  const basePremium = basePremiumOfType(item.type);
90	  const curseSurcharge = isCursed(item) ? basePremium * CURSE_SURCHARGE_RATE : 0;
91	  const enchantmentSurcharge = qualifiesForEnchantmentSurcharge(item)
92	    ? basePremium * ENCHANTMENT_SURCHARGE_RATE
93	    : 0;
94	  return curseSurcharge + enchantmentSurcharge;
95	};
96	
97	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
98	const COMPONENT_BLOCK_SIZE = 3;
99	const COMPONENT_BLOCK_PREMIUM = 60;
100	
101	const isComponent = (type: string): boolean => COMPONENT_TYPES.has(type);
102	
103	/** Tallies anything identified by a type — insured items or damage entries alike. */
104	const countByType = (typed: { type: string }[]): Map<string, number> => {
105	  const counts = new Map<string, number>();
106	  for (const { type } of typed) {
107	    counts.set(type, (counts.get(type) ?? 0) + 1);
108	  }
109	  return counts;
110	};
111	
112	/**
113	 * Items of one type are normally priced individually. The exception is
114	 * components: exactly 3 alike ones form a "building block" priced as a unit.
115	 */
116	const typeGroupPremium = (type: string, count: number): number =>
117	  isComponent(type) && count === COMPONENT_BLOCK_SIZE
118	    ? COMPONENT_BLOCK_PREMIUM
119	    : count * basePremiumOfType(type);
120	
121	const policyBasePremiumOf = (items: Item[]): number =>
122	  [...countByType(items)].reduce(
123	    (sum, [type, count]) => sum + typeGroupPremium(type, count),
124	    0,
125	  );
126	
127	const isLongStanding = (customer: Customer): boolean =>
128	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
129	
130	/** What the policy-wide modifiers are judged against, beyond the items themselves. */
131	interface QuoteContext {
132	  customer: Customer;
133	  isFollowUpContract: boolean;
134	}
135	
136	/**
137	 * Policy-wide modifiers are signed rates charged against the policy base
138	 * premium: surcharges positive, discounts negative.
139	 */
140	const policyModifierRateFor = (context: QuoteContext): number =>
141	  INITIAL_ASSESSMENT_SURCHARGE_RATE -
142	  (isLongStanding(context.customer) ? LOYALTY_DISCOUNT_RATE : 0) -
143	  (context.isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);
144	
145	const itemSurchargesTotal = (items: Item[]): number =>
146	  items.reduce((sum, item) => sum + itemSurchargesOf(item), 0);
147	
148	/**
149	 * Intermediate amounts are kept as exact fractions; only the total is rounded,
150	 * up, in the MHPCO's favour.
151	 */
152	const premiumFor = (items: Item[], context: QuoteContext): number => {
153	  const policyBasePremium = policyBasePremiumOf(items);
154	  const policyModifiers = policyBasePremium * policyModifierRateFor(context);
155	  return Math.ceil(
156	    policyBasePremium + itemSurchargesTotal(items) + policyModifiers + PROCESSING_FEE,
157	  );
158	};
159	
160	const DEDUCTIBLE = 100;
161	const CAP_MULTIPLIER = 2;
162	
163	const insuranceSumOf = (items: Item[]): number =>
164	  items.reduce((sum, item) => sum + termsOfType(item.type).insuranceValue, 0);
165	
166	/** A policy created by a quote step, tracked so later claims can draw on it. */
167	interface Policy {
168	  items: Item[];
169	  remainingCap: number;
170	}
171	
172	/** The most a policy will ever pay out, across all claims against it. */
173	const capFor = (items: Item[]): number => insuranceSumOf(items) * CAP_MULTIPLIER;
174	
175	const openPolicyFor = (items: Item[]): Policy => ({ items, remainingCap: capFor(items) });
176	
177	const REDUCED_REIMBURSEMENT_LEVEL = 8;
178	const REDUCED_REIMBURSEMENT_RATE = 0.5;
179	
180	/** Judged against its own threshold, higher than ENCHANTMENT_SURCHARGE_LEVEL. */
181	const qualifiesForReducedReimbursement = (insuredItem: Item): boolean =>
182	  enchantmentOf(insuredItem) >= REDUCED_REIMBURSEMENT_LEVEL;
183	
184	/** The share of the damage the MHPCO reimburses, before the deductible. */
185	const reimbursementRateFor = (insuredItem: Item): number =>
186	  qualifiesForReducedReimbursement(insuredItem) ? REDUCED_REIMBURSEMENT_RATE : 1;
187	
188	const payoutForDamage = (damage: Damage, insuredItem: Item): number => {
189	  if (damage.amount < 0) {
190	    throw new Error(`damage amount must not be negative: ${String(damage.amount)}`);
191	  }
192	  return damage.amount * reimbursementRateFor(insuredItem) - DEDUCTIBLE;
193	};
194	
195	/**
196	 * The insured item a damage entry draws on. Callers must have cleared the
197	 * damages through rejectDamagesBeyondInsuredCount first, which guarantees a
198	 * match exists; the guard here only discharges that promise for the compiler.
199	 */
200	const insuredItemFor = (damage: Damage, policy: Policy): Item => {
201	  const insuredItem = policy.items.find((item) => item.type === damage.itemType);
202	  if (insuredItem === undefined) {
203	    throw new Error(`claim references uninsured item type ${damage.itemType}`);
204	  }
205	  return insuredItem;
206	};
207	
208	interface Settlement {
209	  payout: number;
210	  remainingCap: number;
211	}
212	
213	/**
214	 * A policy covering N items of a type answers for at most N damage entries of
215	 * it — a second broken sword is not covered by a policy insuring only one.
216	 * This also rejects types the policy does not cover at all (0 insured).
217	 */
218	const rejectDamagesBeyondInsuredCount = (damages: Damage[], policy: Policy): void => {
219	  const insuredCounts = countByType(policy.items);
220	  const damagedCounts = countByType(damages.map(({ itemType }) => ({ type: itemType })));
221	
222	  for (const [type, damaged] of damagedCounts) {
223	    const insured = insuredCounts.get(type) ?? 0;
224	    if (damaged > insured) {
225	      throw new Error(
226	        `claim damages ${String(damaged)} ${type}(s) but only ${String(insured)} insured`,
227	      );
228	    }
229	  }
230	};
231	
232	/**
233	 * Draws against the policy's remaining cap, which it depletes.
234	 * Rounded down, in the MHPCO's favour.
235	 */
236	const settleClaim = (step: ClaimStep, policy: Policy): Settlement => {
237	  rejectDamagesBeyondInsuredCount(step.incident.damages, policy);
238	
239	  const claimed = step.incident.damages.reduce(
240	    (sum, damage) => sum + payoutForDamage(damage, insuredItemFor(damage, policy)),
241	    0,
242	  );
243	  const payout = Math.floor(Math.min(claimed, policy.remainingCap));
244	
245	  policy.remainingCap -= payout;
246	  return { payout, remainingCap: policy.remainingCap };
247	};
248	
249	const policyReferencedBy = (step: ClaimStep, policies: Map<number, Policy>): Policy => {
250	  const policy = policies.get(step.policy);
251	  if (policy === undefined) {
252	    throw new Error(`claim references unknown policy at step ${String(step.policy)}`);
253	  }
254	  return policy;
255	};
256	
257	export const runScenario = (scenario: Scenario): ScenarioOutput => {
258	  const policies = new Map<number, Policy>();
259	
260	  const results = scenario.steps.map((step, stepIndex) => {
261	    if (step.op === "claim") {
262	      return settleClaim(step, policyReferencedBy(step, policies));
263	    }
264	
265	    // Every quote but the first is a follow-up contract for this customer.
266	    const isFollowUpContract = policies.size > 0;
267	    policies.set(stepIndex, openPolicyFor(step.items));
268	
269	    return {
270	      premium: premiumFor(step.items, { customer: scenario.customer, isFollowUpContract }),
271	    };
272	  });
273	
274	  return { results };
275	};
