3	/** Resolves once stdin is exhausted — the whole scenario, never a partial one. */
4	const readAllStdin = async (): Promise<string> => {
5	  const chunks: Buffer[] = [];
6	  for await (const chunk of process.stdin) {
7	    chunks.push(chunk as Buffer);
8	  }
9	  return Buffer.concat(chunks).toString("utf8");
10	};
11	
12	/** The sole point where untrusted input is taken on trust as a Scenario. */
13	const parseScenario = (input: string): Scenario => JSON.parse(input) as Scenario;
14	
15	const describe = (error: unknown): string =>
16	  error instanceof Error ? error.message : String(error);
17	
18	/** Every failure — reading, parsing, or running — leaves stdout empty. */
19	try {
20	  const scenario = parseScenario(await readAllStdin());
21	  process.stdout.write(JSON.stringify(runScenario(scenario)));
22	} catch (error) {
23	  process.stderr.write(`${describe(error)}\n`);
24	  process.exit(1);
25	}
